def compute(vars):
    expense_2019 = vars["v1"]
    expense_2018 = vars["v2"]

    if expense_2019 < 50000:
        year = 2019
    elif expense_2018 < 50000:
        year = 2018
    else:
        year = None

    return {
        "value": year,
        "trace": {
            "expense_2019": expense_2019,
            "expense_2018": expense_2018,
            "threshold": 50000,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
